          "code": "import numpy as np\n\nrng = np.random.default_rng(2611)\n\n# -----------------------------------------------------------------------------\n# First-Principles: Empirical Bayes Smoothing (Micci-Barreca 2001) & OOF Encoding\n# -----------------------------------------------------------------------------\n# Bangkitkan 1.200 transaksi pembayaran across 180 merchant (distribusi Zipf / long-tail!)\nn_samples = 1200\nn_merchants = 180\nzipf_weights = 1.0 / (np.arange(1, n_merchants + 1) ** 1.15)\nzipf_weights /= zipf_weights.sum()\n\nmerchant_ids = rng.choice(n_merchants, size=n_samples, p=zipf_weights)\n# Risiko dasar laten per merchant (Beta-Binomial realistis: rata-rata ~14% fraud/chargeback)\ntrue_merchant_risk = rng.beta(1.4, 8.6, size=n_merchants)\ny = (rng.uniform(size=n_samples) < true_merchant_risk[merchant_ids]).astype(float)\n\n# 1) Bandingkan error estimasi kategori langka (n_c <= 3) vs populer (n_c >= 20): Naive vs Empirical Bayes\nglobal_prior = float(y.mean())\ncounts = np.bincount(merchant_ids, minlength=n_merchants)\nsums = np.bincount(merchant_ids, weights=y, minlength=n_merchants)\n\nraw_mean = np.where(counts > 0, sums / np.maximum(counts, 1), global_prior)\nm_smooth = 15.0\neb_mean = (sums + m_smooth * global_prior) / (counts + m_smooth)\n\nrare_mask = (counts >= 1) & (counts <= 3)\npop_mask = counts >= 20\nmse_rare_raw = float(np.mean((raw_mean[rare_mask] - true_merchant_risk[rare_mask]) ** 2))\nmse_rare_eb = float(np.mean((eb_mean[rare_mask] - true_merchant_risk[rare_mask]) ** 2))\nmse_pop_raw = float(np.mean((raw_mean[pop_mask] - true_merchant_risk[pop_mask]) ** 2))\nmse_pop_eb = float(np.mean((eb_mean[pop_mask] - true_merchant_risk[pop_mask]) ** 2))\n\n# 2) Implementasi Out-of-Fold (5-Fold) Empirical Bayes Target Encoding dari nol\nn_splits = 5\nperm = rng.permutation(n_samples)\nfold_ids = np.empty(n_samples, dtype=int)\nfold_ids[perm] = np.arange(n_samples) % n_splits\n\noof_encoded = np.empty(n_samples, dtype=float)\nnaive_infold = np.empty(n_samples, dtype=float)\n\nfor f in range(n_splits):\n    tr_idx = fold_ids != f\n    va_idx = fold_ids == f\n    prior_f = float(y[tr_idx].mean())\n    c_f = np.bincount(merchant_ids[tr_idx], minlength=n_merchants)\n    s_f = np.bincount(merchant_ids[tr_idx], weights=y[tr_idx], minlength=n_merchants)\n    enc_table_f = (s_f + m_smooth * prior_f) / (c_f + m_smooth)\n    oof_encoded[va_idx] = enc_table_f[merchant_ids[va_idx]]\n\n# Bandingkan korelasi dengan label y pada kategori langka (n_c <= 2): Naive memalsukan sinyal!\nnaive_infold = raw_mean[merchant_ids]\nrare_rows = counts[merchant_ids] <= 2\ncorr_naive_rare = float(np.corrcoef(naive_infold[rare_rows], y[rare_rows])[0, 1])\ncorr_oof_rare = float(np.corrcoef(oof_encoded[rare_rows], y[rare_rows])[0, 1])\n\n# 3) Weight of Evidence (WoE) & Information Value (IV) untuk 5 tier frekuensi merchant\ntier_edges = [0, 3, 10, 30, 80, 9999]\ntier_labels = [\"T1_UltraRare(1-3)\", \"T2_Rare(4-10)\", \"T3_Mid(11-30)\", \"T4_High(31-80)\", \"T5_Top(>80)\"]\nrow_counts = counts[merchant_ids]\ntier_idx = np.digitize(row_counts, tier_edges[1:-1], right=True)\n\ntotal_bad = float(y.sum())\ntotal_good = float((1.0 - y).sum())\niv_total = 0.0\nprint(\"=== 1. Empirical Bayes Shrinkage (m = 15) vs Naive Sample Mean ===\")\nprint(f\"Prior Global Chargeback (y_bar)          : {global_prior:.4f} (N={n_samples}, {int((counts>0).sum())} merchant aktif)\")\nprint(f\"MSE Estimasi Risiko [Langka n_c<=3]      : Naive={mse_rare_raw:.4f} -> EB={mse_rare_eb:.4f} ({mse_rare_raw/mse_rare_eb:.2f}x lebih akurat!)\")\nprint(f\"MSE Estimasi Risiko [Populer n_c>=20]    : Naive={mse_pop_raw:.4f} -> EB={mse_pop_eb:.4f}\")\nprint(f\"Korelasi Fitur-Target [Baris n_c<=2]     : Naive In-Sample={corr_naive_rare:.4f} (BOCOR!) vs OOF-EB={corr_oof_rare:.4f}\")\n\nprint(\"\\n=== 2. Audit Shrinkage Weight lambda(n_c) = n_c / (n_c + m) ===\")\nfor nc_ex in [1, 3, 15, 60]:\n    lam = nc_ex / (nc_ex + m_smooth)\n    print(f\"  n_c={nc_ex:2d} -> bobot data kategori lambda={lam:.3f}, bobot prior global (1-lambda)={1.0-lam:.3f}\")\n\nprint(\"\\n=== 3. Tabel WoE & Information Value (Laplace alpha=0.5) ===\")\nfor t_i, lbl in enumerate(tier_labels):\n    mask_t = tier_idx == t_i\n    bad_t = float(y[mask_t].sum())\n    good_t = float((1.0 - y[mask_t]).sum())\n    p_bad = (bad_t + 0.5) / (total_bad + 0.5 * len(tier_labels))\n    p_good = (good_t + 0.5) / (total_good + 0.5 * len(tier_labels))\n    woe_t = float(np.log(p_bad / p_good))\n    iv_t = (p_bad - p_good) * woe_t\n    iv_total += iv_t\n    print(f\"  {lbl:18s} | n={int(mask_t.sum()):4d} | bad={int(bad_t):3d} | WoE={woe_t:+.4f} | IV_bin={iv_t:.4f}\")\nprint(f\"Total Information Value (IV)             : {iv_total:.4f}\")",
