          "id": "code-ml-26-2-ch26_2_sklearn",
          "title": "Scikit-Learn 1.9: Ordinal vs Sin/Cos vs SplineTransformer(periodic [0,24]) + Interaksi",
          "language": "python",
          "filename": "26_2_sklearn_periodic_spline_interactions.py",
          "code": "import numpy as np\nimport pandas as pd\nfrom sklearn.compose import ColumnTransformer\nfrom sklearn.linear_model import Ridge\nfrom sklearn.metrics import root_mean_squared_error\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import FunctionTransformer, PolynomialFeatures, SplineTransformer, StandardScaler\n\nrng = np.random.default_rng(2622)\n\n# -----------------------------------------------------------------------------\n# Modern Scikit-Learn 1.9: Ordinal vs Sin/Cos vs SplineTransformer(periodic) + Interaksi\n# -----------------------------------------------------------------------------\n# Data permintaan kurir makanan selama 60 hari per jam (1.440 observasi kronologis)\nn_hours = 60 * 24\nt_idx = np.arange(n_hours)\nhour = (t_idx % 24).astype(float)\nis_weekend = (((t_idx // 24) % 7) >= 5).astype(float)\nrain_mm = np.maximum(0.0, rng.normal(loc=1.5, scale=3.2, size=n_hours))\n\n# Pola permintaan nyata: puncak tajam jam 12.5 & 19.5, lonjakan tengah malam akhir pekan,\n# plus interaksi kuat hujan x jam makan malam!\nbase_curve = (\n    30.0\n    + 42.0 * np.exp(-0.5 * ((hour - 12.5) / 1.6) ** 2)\n    + 58.0 * np.exp(-0.5 * ((hour - 19.5) / 1.4) ** 2)\n    + 18.0 * is_weekend * np.exp(-0.5 * (np.minimum(hour, 24.0 - hour) / 1.8) ** 2)\n)\nrain_interaction = 4.2 * rain_mm * (0.4 + np.exp(-0.5 * ((hour - 19.5) / 2.2) ** 2))\norders = base_curve + rain_interaction + rng.normal(0.0, 3.8, size=n_hours)\n\ndf = pd.DataFrame({\"hour\": hour, \"is_weekend\": is_weekend, \"rain_mm\": rain_mm})\n# Split temporal ketat: 45 hari pertama untuk latih, 15 hari terakhir untuk uji!\nsplit_pt = 45 * 24\nX_tr, X_te = df.iloc[:split_pt], df.iloc[split_pt:]\ny_tr, y_te = orders[:split_pt], orders[split_pt:]\n\n# Model 1: Baseline Linier Ordinal mentah (gagal menangkap non-linearitas & batas 23->0)\nm_ord = Pipeline([(\"sc\", StandardScaler()), (\"reg\", Ridge(alpha=1.0))]).fit(X_tr, y_tr)\nrmse_ord = root_mean_squared_error(y_te, m_ord.predict(X_te))\n\n# Model 2: Cyclic Sin/Cos orde-1 untuk jam\ndef add_sincos(X_in):\n    h = np.asarray(X_in)[:, 0]\n    return np.column_stack([np.sin(2.0 * np.pi * h / 24.0), np.cos(2.0 * np.pi * h / 24.0)])\n\nm_cyc = Pipeline([\n    (\"prep\", ColumnTransformer([\n        (\"cyc\", FunctionTransformer(add_sincos), [\"hour\"]),\n        (\"num\", StandardScaler(), [\"is_weekend\", \"rain_mm\"]),\n    ])),\n    (\"reg\", Ridge(alpha=1.0)),\n]).fit(X_tr, y_tr)\nrmse_cyc = root_mean_squared_error(y_te, m_cyc.predict(X_te))\n\n# Model 3: Periodic Cubic B-Spline dengan knot EKSPLISIT [0, 24] (bukan [0, 23]!)\nperiodic_knots = np.linspace(0.0, 24.0, 9).reshape(-1, 1)\nm_spline = Pipeline([\n    (\"prep\", ColumnTransformer([\n        (\"sp\", SplineTransformer(degree=3, knots=periodic_knots, extrapolation=\"periodic\", include_bias=False), [\"hour\"]),\n        (\"num\", StandardScaler(), [\"is_weekend\", \"rain_mm\"]),\n    ])),\n    (\"reg\", Ridge(alpha=1.0)),\n]).fit(X_tr, y_tr)\nrmse_spline = root_mean_squared_error(y_te, m_spline.predict(X_te))\n\n# Model 4: Periodic B-Spline + Interaksi Pasangan (menangkap hujan x jam sibuk & weekend x tengah malam!)\nm_spline_inter = Pipeline([\n    (\"prep\", ColumnTransformer([\n        (\"sp\", SplineTransformer(degree=3, knots=periodic_knots, extrapolation=\"periodic\", include_bias=False), [\"hour\"]),\n        (\"num\", StandardScaler(), [\"is_weekend\", \"rain_mm\"]),\n    ])),\n    (\"inter\", PolynomialFeatures(degree=2, interaction_only=True, include_bias=False)),\n    (\"reg\", Ridge(alpha=5.0)),\n]).fit(X_tr, y_tr)\nrmse_inter = root_mean_squared_error(y_te, m_spline_inter.predict(X_te))\n\n# Audit kontinuitas batas periodik tepat di h=0.00 vs h=24.00 pada SplineTransformer\nsp_step = m_spline.named_steps[\"prep\"].named_transformers_[\"sp\"]\nb_at_0 = sp_step.transform(pd.DataFrame({\"hour\": [0.0]}))\nb_at_24 = sp_step.transform(pd.DataFrame({\"hour\": [24.0]}))\nboundary_gap = float(np.max(np.abs(b_at_0 - b_at_24)))\n\nprint(\"=== Evaluasi Temporal Holdout (Hari 46-60) pada Ridge Regression ===\")\nprint(f\"1) Ordinal hour (0..23)                 -> Test RMSE = {rmse_ord:6.3f} order/jam\")\nprint(f\"2) Cyclic sin/cos orde-1                -> Test RMSE = {rmse_cyc:6.3f} order/jam\")\nprint(f\"3) Periodic Cubic Spline [0, 24]        -> Test RMSE = {rmse_spline:6.3f} order/jam\")\nprint(f\"4) Periodic Spline + Pairwise Interact  -> Test RMSE = {rmse_inter:6.3f} order/jam (mendekati noise floor 3.8!)\")\nprint(f\"Kontinuitas Batas Periodic ||B(0)-B(24)||_inf = {boundary_gap:.2e} (0 = mulus C^2 melintasi tengah malam!)\")",
          "expectedOutput": "=== Evaluasi Temporal Holdout (Hari 46-60) pada Ridge Regression ===\n1) Ordinal hour (0..23)                 -> Test RMSE = 15.840 order/jam\n2) Cyclic sin/cos orde-1                -> Test RMSE = 14.792 order/jam\n3) Periodic Cubic Spline [0, 24]        -> Test RMSE =  8.255 order/jam\n4) Periodic Spline + Pairwise Interact  -> Test RMSE =  7.691 order/jam (mendekati noise floor 3.8!)\nKontinuitas Batas Periodic ||B(0)-B(24)||_inf = 0.00e+00 (0 = mulus C^2 melintasi tengah malam!)",
          "actualOutput": "=== Evaluasi Temporal Holdout (Hari 46-60) pada Ridge Regression ===\n1) Ordinal hour (0..23)                 -> Test RMSE = 15.840 order/jam\n2) Cyclic sin/cos orde-1                -> Test RMSE = 14.792 order/jam\n3) Periodic Cubic Spline [0, 24]        -> Test RMSE =  8.255 order/jam\n4) Periodic Spline + Pairwise Interact  -> Test RMSE =  7.691 order/jam (mendekati noise floor 3.8!)\nKontinuitas Batas Periodic ||B(0)-B(24)||_inf = 0.00e+00 (0 = mulus C^2 melintasi tengah malam!)",
