          "filename": "26_3_rubin_mechanisms_and_mice_scratch.py",
          "code": "import numpy as np\n\nrng = np.random.default_rng(2631)\n\n# -----------------------------------------------------------------------------\n# First-Principles: Generator Rubin (MCAR/MAR/MNAR), Uji Informativitas & MICE Loop\n# -----------------------------------------------------------------------------\nn = 1400\n# Dua fitur berkorelasi kuat: x_age (selalu teramati) & x_income (berpotensi hilang)\nx_age = rng.normal(loc=38.0, scale=10.0, size=n)\nx_income_true = 4.0 + 0.35 * x_age + rng.normal(loc=0.0, scale=2.2, size=n)  # juta Rp/bulan\n# Target gagal bayar: sangat dipengaruhi pendapatan rendah!\nlogit_y = 2.6 - 0.28 * x_income_true - 0.02 * x_age\ny = (rng.uniform(size=n) < (1.0 / (1.0 + np.exp(-logit_y)))).astype(int)\n\n# Bangkitkan 3 mekanisme missingness Rubin dengan laju hilang ~28% yang sebanding:\n# (a) MCAR: murni koin acak independen dari X dan Y\nm_mcar = rng.uniform(size=n) < 0.28\n# (b) MAR : bergantung HANYA pada fitur teramati x_age (nasabah muda lebih sering mengosongkan)\np_mar = 1.0 / (1.0 + np.exp(0.18 * (x_age - 31.5)))\nm_mar = rng.uniform(size=n) < p_mar\n# (c) MNAR: bergantung langsung pada x_income_true tak teramati (pendapatan rendah sengaja kosong!)\np_mnar = 1.0 / (1.0 + np.exp(0.65 * (x_income_true - 15.2)))\nm_mnar = rng.uniform(size=n) < p_mnar\n\nprint(\"=== 1. Diagnostik Statistik 3 Mekanisme Missingness Rubin (1976) ===\")\nfor name, mask in [(\"MCAR (Acak Murni)\", m_mcar), (\"MAR  (Dep. x_age)\", m_mar), (\"MNAR (Dep. x_inc)\", m_mnar)]:\n    rate_m1 = float(y[mask].mean())\n    rate_m0 = float(y[~mask].mean())\n    age_diff = float(x_age[mask].mean() - x_age[~mask].mean())\n    true_inc_gap = float(x_income_true[mask].mean() - x_income_true[~mask].mean())\n    print(f\"{name:18s} | null={100*mask.mean():4.1f}% | P(Y=1|M=1)={rate_m1:.3f} vs P(Y=1|M=0)={rate_m0:.3f} \"\n          f\"| dAge={age_diff:+5.2f} | TrueIncGap={true_inc_gap:+5.2f}\")\n\n# 2) Implementasi MICE (Chained Equations Ridge Regression) dari nol pada data MAR 3-kolom\nx_savings_true = 1.5 + 0.60 * x_income_true + 0.12 * x_age + rng.normal(0.0, 1.5, size=n)\nX_complete = np.column_stack([x_age, x_income_true, x_savings_true])\nX_mar = X_complete.copy()\nm_sav_mar = rng.uniform(size=n) < (1.0 / (1.0 + np.exp(0.15 * (x_age - 30.0))))\nX_mar[m_mar, 1] = np.nan\nX_mar[m_sav_mar, 2] = np.nan\n\n# Baseline Simple Median Imputation vs MICE 6 Iterasi\nX_med = X_mar.copy()\nfor j in [1, 2]:\n    X_med[np.isnan(X_med[:, j]), j] = np.nanmedian(X_med[:, j])\n\nX_mice = X_med.copy()\nlam_ridge = 1e-2\nfor it in range(6):\n    for j in [1, 2]:\n        obs = ~np.isnan(X_mar[:, j])\n        mis = ~obs\n        other = [c for c in range(3) if c != j]\n        A_tr = np.column_stack([np.ones(obs.sum()), X_mice[obs][:, other]])\n        y_tr_j = X_mar[obs, j]\n        # Solusi Ridge tertutup (A^T A + lambda I) w = A^T y\n        reg = lam_ridge * np.eye(A_tr.shape[1])\n        reg[0, 0] = 0.0\n        w = np.linalg.solve(A_tr.T @ A_tr + reg, A_tr.T @ y_tr_j)\n        A_mis = np.column_stack([np.ones(mis.sum()), X_mice[mis][:, other]])\n        X_mice[mis, j] = A_mis @ w\n\nrmse_med_inc = float(np.sqrt(np.mean((X_med[m_mar, 1] - x_income_true[m_mar]) ** 2)))\nrmse_mice_inc = float(np.sqrt(np.mean((X_mice[m_mar, 1] - x_income_true[m_mar]) ** 2)))\nrmse_med_sav = float(np.sqrt(np.mean((X_med[m_sav_mar, 2] - x_savings_true[m_sav_mar]) ** 2)))\nrmse_mice_sav = float(np.sqrt(np.mean((X_mice[m_sav_mar, 2] - x_savings_true[m_sav_mar]) ** 2)))\n\nprint(\"\\n=== 2. Akurasi Rekonstruksi Nilai Hilang pada Rezim MAR (Median vs MICE 6-Iter) ===\")\nprint(f\"Kolom income  : Median RMSE = {rmse_med_inc:.3f} -> MICE RMSE = {rmse_mice_inc:.3f} ({100*(1-rmse_mice_inc/rmse_med_inc):.1f}% lebih akurat)\")\nprint(f\"Kolom savings : Median RMSE = {rmse_med_sav:.3f} -> MICE RMSE = {rmse_mice_sav:.3f} ({100*(1-rmse_mice_sav/rmse_med_sav):.1f}% lebih akurat)\")",
          "expectedOutput": "=== 1. Diagnostik Statistik 3 Mekanisme Missingness Rubin (1976) ===\nMCAR (Acak Murni)  | null=29.3% | P(Y=1|M=1)=0.093 vs P(Y=1|M=0)=0.087 | dAge=-0.48 | TrueIncGap=-0.10\nMAR  (Dep. x_age)  | null=33.3% | P(Y=1|M=1)=0.180 vs P(Y=1|M=0)=0.043 | dAge=-12.17 | TrueIncGap=-4.17\nMNAR (Dep. x_inc)  | null=34.9% | P(Y=1|M=1)=0.198 vs P(Y=1|M=0)=0.030 | dAge=-11.77 | TrueIncGap=-5.76\n\n=== 2. Akurasi Rekonstruksi Nilai Hilang pada Rezim MAR (Median vs MICE 6-Iter) ===\nKolom income  : Median RMSE = 5.434 -> MICE RMSE = 1.931 (64.5% lebih akurat)\nKolom savings : Median RMSE = 4.984 -> MICE RMSE = 1.653 (66.8% lebih akurat)",
