          "code": "import numpy as np\nfrom scipy.stats import binomtest\nfrom sklearn.ensemble import RandomForestClassifier\n\nrng = np.random.default_rng(2641)\n\n# -----------------------------------------------------------------------------\n# First-Principles: Algoritma Boruta (Kursa & Rudnicki 2010) Lengkap dari Nol\n# -----------------------------------------------------------------------------\nn = 650\n# 2 fitur linier kuat (lin0, lin1), 2 fitur interaksi XOR murni (xor0, xor1),\n# 1 fitur kolinear klon lin0 (clone0), dan 5 fitur noise murni (noise0..noise4)!\nlin0 = rng.normal(0.0, 1.0, size=n)\nlin1 = rng.normal(0.0, 1.0, size=n)\nxor0 = rng.normal(0.0, 1.0, size=n)\nxor1 = rng.normal(0.0, 1.0, size=n)\nclone0 = lin0 + rng.normal(0.0, 0.25, size=n)\nnoises = rng.normal(0.0, 1.0, size=(n, 5))\n\nX = np.column_stack([lin0, lin1, xor0, xor1, clone0, noises])\nnames = [\"lin0\", \"lin1\", \"xor0\", \"xor1\", \"clone0\", \"noise0\", \"noise1\", \"noise2\", \"noise3\", \"noise4\"]\n\n# Target menggabungkan sinyal linier + sinyal XOR non-linier murni (korelasi univariat xor0/xor1 == 0!)\nlogit = 1.4 * lin0 - 1.1 * lin1 + 2.2 * np.where(xor0 * xor1 > 0, 1.0, -1.0)\ny = (rng.uniform(size=n) < (1.0 / (1.0 + np.exp(-logit)))).astype(int)\n\n# 1) Buktikan seleksi univariat Pearson GAGAL TOTAL pada interaksi XOR\nabs_corr = np.array([abs(np.corrcoef(X[:, j], y)[0, 1]) for j in range(X.shape[1])])\n\n# 2) Jalankan Boruta: T=20 putaran, setiap putaran buat shadow features teracak -> bandingkan vs max(shadow)\nn_trials = 20\nd = X.shape[1]\nhits = np.zeros(d, dtype=int)\nmean_imp = np.zeros(d, dtype=float)\nmean_shadow_max = 0.0\n\nfor t in range(n_trials):\n    # Permutasi independen tiap kolom untuk membangun matriks shadow X_tilde\n    X_shadow = np.column_stack([rng.permutation(X[:, j]) for j in range(d)])\n    X_aug = np.hstack([X, X_shadow])\n    rf = RandomForestClassifier(\n        n_estimators=45, max_depth=6, max_features=\"sqrt\", random_state=100 + t, n_jobs=1\n    )\n    rf.fit(X_aug, y)\n    imp = rf.feature_importances_\n    real_imp = imp[:d]\n    shadow_max = float(np.max(imp[d:]))\n    hits += (real_imp > shadow_max).astype(int)\n    mean_imp += real_imp / n_trials\n    mean_shadow_max += shadow_max / n_trials\n\n# Keputusan statistik dua-sisi Binomial(T, 0.5) dengan koreksi Bonferroni (alpha = 0.05 / d)\nalpha_bonf = 0.05 / d\nprint(\"=== Perbandingan Korelasi Univariat vs Boruta Shadow Features (T=20, Bonferroni) ===\")\nprint(f\"Rata-rata Ambang Shadow Max (MZSA) = {mean_shadow_max:.4f} | Alpha Bonferroni = {alpha_bonf:.4f}\\n\")\nfor j, name in enumerate(names):\n    p_val = float(binomtest(int(hits[j]), n_trials, p=0.5, alternative=\"two-sided\").pvalue)\n    if hits[j] > n_trials / 2 and p_val < alpha_bonf:\n        decision = \"CONFIRMED\"\n    elif hits[j] < n_trials / 2 and p_val < alpha_bonf:\n        decision = \"REJECTED\"\n    else:\n        decision = \"TENTATIVE\"\n    print(f\"  {name:7s} | |r_Pearson|={abs_corr[j]:.3f} | MeanImp={mean_imp[j]:.4f} | Hits={hits[j]:2d}/{n_trials} | p={p_val:.5f} | {decision}\")",
          "expectedOutput": "=== Perbandingan Korelasi Univariat vs Boruta Shadow Features (T=20, Bonferroni) ===\nRata-rata Ambang Shadow Max (MZSA) = 0.0455 | Alpha Bonferroni = 0.0050\n\n  lin0    | |r_Pearson|=0.291 | MeanImp=0.1119 | Hits=20/20 | p=0.00000 | CONFIRMED\n  lin1    | |r_Pearson|=0.281 | MeanImp=0.1564 | Hits=20/20 | p=0.00000 | CONFIRMED\n  xor0    | |r_Pearson|=0.028 | MeanImp=0.0575 | Hits=18/20 | p=0.00040 | CONFIRMED\n  xor1    | |r_Pearson|=0.028 | MeanImp=0.0610 | Hits=19/20 | p=0.00004 | CONFIRMED\n  clone0  | |r_Pearson|=0.287 | MeanImp=0.1087 | Hits=20/20 | p=0.00000 | CONFIRMED\n  noise0  | |r_Pearson|=0.003 | MeanImp=0.0282 | Hits= 0/20 | p=0.00000 | REJECTED\n  noise1  | |r_Pearson|=0.004 | MeanImp=0.0301 | Hits= 0/20 | p=0.00000 | REJECTED\n  noise2  | |r_Pearson|=0.054 | MeanImp=0.0301 | Hits= 0/20 | p=0.00000 | REJECTED\n  noise3  | |r_Pearson|=0.029 | MeanImp=0.0322 | Hits= 0/20 | p=0.00000 | REJECTED\n  noise4  | |r_Pearson|=0.001 | MeanImp=0.0413 | Hits= 6/20 | p=0.11532 | TENTATIVE",
          "actualOutput": "=== Perbandingan Korelasi Univariat vs Boruta Shadow Features (T=20, Bonferroni) ===\nRata-rata Ambang Shadow Max (MZSA) = 0.0455 | Alpha Bonferroni = 0.0050\n\n  lin0    | |r_Pearson|=0.291 | MeanImp=0.1119 | Hits=20/20 | p=0.00000 | CONFIRMED\n  lin1    | |r_Pearson|=0.281 | MeanImp=0.1564 | Hits=20/20 | p=0.00000 | CONFIRMED\n  xor0    | |r_Pearson|=0.028 | MeanImp=0.0575 | Hits=18/20 | p=0.00040 | CONFIRMED\n  xor1    | |r_Pearson|=0.028 | MeanImp=0.0610 | Hits=19/20 | p=0.00004 | CONFIRMED\n  clone0  | |r_Pearson|=0.287 | MeanImp=0.1087 | Hits=20/20 | p=0.00000 | CONFIRMED\n  noise0  | |r_Pearson|=0.003 | MeanImp=0.0282 | Hits= 0/20 | p=0.00000 | REJECTED\n  noise1  | |r_Pearson|=0.004 | MeanImp=0.0301 | Hits= 0/20 | p=0.00000 | REJECTED\n  noise2  | |r_Pearson|=0.054 | MeanImp=0.0301 | Hits= 0/20 | p=0.00000 | REJECTED\n  noise3  | |r_Pearson|=0.029 | MeanImp=0.0322 | Hits= 0/20 | p=0.00000 | REJECTED\n  noise4  | |r_Pearson|=0.001 | MeanImp=0.0413 | Hits= 6/20 | p=0.11532 | TENTATIVE",
